const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  // Get Latest Readings ตอนนี้ pass ทั้ง batch context (batch_id, beer_name,
  // current_phase, prep_alerted_for_phase, start_date) และ series ทั้งเส้นมาด้วยกัน
  const batch = it.json;
  const r = it.json;

  const startDate = new Date(batch.start_date);
  const hoursSinceStart = (Date.now() - startDate.getTime()) / 3600000;

  const pillSeries = Array.isArray(r.pill_series) ? r.pill_series : [];
  const controllerSeries = Array.isArray(r.controller_series) ? r.controller_series : [];
  const controlSeries = Array.isArray(r.control_series) ? r.control_series : [];

  const latestPill = pillSeries.length ? pillSeries[pillSeries.length - 1] : null;
  const latestController = controllerSeries.length ? controllerSeries[controllerSeries.length - 1] : null;

  // อุณหภูมิหมักจริงของ batch นี้ (เฉลี่ยจาก Pill ช่วง 72 ชม.แรก ก่อนจะมีการปรับ
  // อุณหภูมิเพื่อทำ diacetyl_rest/cold_crash) ใช้เป็น baseline เทียบแบบสัมพัทธ์
  // แทนเลของศาตายตัว เพราะแต่ละ batch/ยีสต์หมักที่อุณหภูมิไม่เท่ากัน
  const fermentationTempPoints = pillSeries.filter(p => {
    const hoursSincePoint = (new Date(p.t) - startDate) / 3600000;
    return hoursSincePoint >= 0 && hoursSincePoint <= 72 && p.temp != null;
  });
  const fermentationBaselineTemp = fermentationTempPoints.length
    ? Number((fermentationTempPoints.reduce((sum, p) => sum + p.temp, 0) / fermentationTempPoints.length).toFixed(2))
    : null;

  // เก็บ velocity คร่าวๆ ไว้บันทึกลง phase_log อ้างอิงเท่านั้น ไม่ได้ใช้เป็น
  // หลักฐานตัดสินเฟส เพราะ AI เห็นกราฟทั้งเส้นตรงๆ ด้านล่างอยู่แล้ว
  let loggedVelocity = null;
  if (pillSeries.length >= 2) {
    const first = pillSeries[0], last = pillSeries[pillSeries.length - 1];
    const hoursSpan = (new Date(last.t) - new Date(first.t)) / 3600000;
    if (hoursSpan > 0 && first.sg != null && last.sg != null) {
      loggedVelocity = (last.sg - first.sg) / (hoursSpan / 24);
    }
  }

  const pillSeriesText = pillSeries.length
    ? pillSeries.map(p => `${p.t} | SG=${p.sg != null ? p.sg.toFixed(4) : '-'} | temp=${p.temp ?? '-'}°C`).join('\n')
    : '(ไม่มีข้อมูล)';
  const controllerSeriesText = controllerSeries.length
    ? controllerSeries.map(p => `${p.t} | temp=${p.temp ?? '-'}°C | target=${p.target ?? '-'}°C`).join('\n')
    : '(ไม่มีข้อมูล)';
  const controlSeriesText = controlSeries.length
    ? controlSeries.map(c => `${c.t} | เดิม ${c.old ?? '-'}°C → ใหม่ ${c.new ?? '-'}°C | โดย ${c.by ?? '-'}${c.remark ? ' | เหตุผล: ' + c.remark : ''}`).join('\n')
    : '(ไม่มีการปรับ target ด้วยมือในช่วงนี้)';

  // ข้อมูล recipe/ยีสต์จาก Brewfather (ถ้า batch นี้ผูก recipe ไว้ตอน /ferment_start)
  const fermentationSteps = Array.isArray(r.fermentation_steps) ? r.fermentation_steps : [];
  const fermentationStepsText = fermentationSteps.length
    ? fermentationSteps.map(s => `${s.name || s.type}: ${s.stepTemp}°C x ${s.stepTime} วัน (${s.type})`).join('\n')
    : '(ไม่มีแผนหมักจาก recipe)';
  const recipeContextText = r.recipe_name
    ? `\nข้อมูลจากสูตร Brewfather ที่ผูกไว้กับ batch นี้ ("${r.recipe_name}", สไตล์ ${r.style_name ?? 'ไม่ระบุ'}):\n` +
      `- ยีสต์: ${r.yeast_name ?? 'ไม่ระบุ'}${r.yeast_min_temp_c != null ? ` (ช่วงอุณหภูมิที่ยีสต์นี้รองรับ: ${r.yeast_min_temp_c}-${r.yeast_max_temp_c}°C, attenuation ${r.yeast_min_attenuation ?? '-'}-${r.yeast_max_attenuation ?? r.yeast_attenuation ?? '-'}%)` : ''}\n` +
      `- แผนขั้นตอนอุณหภูมิหมักตามสูตร (ไล่ตามลำดับ):\n${fermentationStepsText}\n` +
      `⚠️ **ใช้แผนนี้เป็นข้อมูลอ้างอิงสำหรับ "ควรตั้ง target ไปเท่าไหร่" เท่านั้น ห้ามใช้จำนวนวัน/ลำดับ step ในแผนมาตัดสินว่า "ถึงเวลาเปลี่ยนเฟสหรือยัง" — การตัดสินเฟส/approaching_transition ต้องดูจากอุณหภูมิ Pill และกราฟ gravity จริงเท่านั้นเหมือนเดิมทุกประการ เพราะการหมักจริงเสร็จเร็ว/ช้ากว่าแผนได้เสมอ**\n`
    : '';

  const promptText = `คุณคือผู้เชี่ยวชาญการหมักเบียร์ (อ้างอิงหลักการจาก BJCP Yeast & Fermentation guide, John Palmer "How to Brew", Brew Your Own Fermentation Timeline) วิเคราะห์ว่า batch นี้อยู่เฟสไหนใน 6 เฟสนี้ โดยดูจาก "กราฟ" gravity/อุณหภูมิทั้งเส้นที่ให้ด้านล่าง (เรียงตามเวลา จากเก่าไปใหม่) ไม่ใช่แค่จุดเดียว:

1. lag (0-24 ชม.แรกหลัง pitch): ยีสต์ปรับตัว ยังไม่มี krausen ชัดเจน กราฟ gravity แทบไม่ขยับจากค่าเริ่มต้น แทบไม่มีผลต่างอุณหภูมิระหว่าง pill กับตู้ควบคุม

2. active_ferment (วันที่ 1-4, หนักสุดมักอยู่ใน 48-72 ชม.แรก): high krausen, กราฟ gravity ลาดชันลงเร็วที่สุดของทั้งเส้น, pill มักอุ่นกว่าตู้ควบคุมชัดเจน (2-5°C, ปฏิกิริยาคายความร้อน)

3. slowing_ferment: กราฟ gravity เริ่มโค้งผ่อนความชันลงจากช่วงชันสุด แต่ยังลดต่อเนื่องชัดเจน (ไม่แบนราบ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมเริ่มแคบลง

4. fg_stable: กราฟ gravity แบนราบต่อเนื่องอย่างน้อย 24-48 ชม. (ไม่ลดต่อแล้วอย่างมีนัยสำคัญ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมใกล้ 0
   ⚠️ ถ้ากราฟแบนเร็วผิดปกติ (เช่นภายใน 2-3 วันแรก) หรือแบนที่ค่าซึ่งยังสูงมากเทียบกับช่วงต้นกราฟ อาจเป็น "stuck fermentation" ให้ระบุความสงสัยไว้ใน reasoning ด้วย (ไม่ต้องเปลี่ยน phase ที่ตอบ แค่เตือนไว้)

5. diacetyl_rest: ต้องผ่าน fg_stable มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง ไม่ใช่อุณหภูมิตู้ควบคุม) ถูกยกขึ้นจาก "อุณหภูมิหมักปกติของ batch นี้" (ดูค่าที่ให้ไว้ด้านล่าง) ประมาณ +2 ถึง +4°C ค้างไว้ 2-3 วัน (จำเป็นสำหรับ lager, แนะนำสำหรับ ale ส่วนใหญ่แม้ไม่บังคับ) — **นี่คือช่วงสัมพัทธ์ ไม่ใช่ตัวเลของศาตายตัว** เพราะแต่ละ batch/ยีสต์หมักที่อุณหภูมิต่างกัน (เช่น batch ที่หมักปกติ 18°C แล้วยกไป 20-22°C ก็นับเป็น diacetyl_rest ได้ ไม่จำเป็นต้องอยู่ในช่วง 16-18°C แบบตายตัว) ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเสมอ ส่วน target/อุณหภูมิตู้ควบคุมเป็นแค่ข้อมูลเสริมว่าตู้กำลังพยายามไล่ตามคำสั่งอยู่หรือยัง (ห้ามใช้แค่ target/ตู้ยังไม่ถึงมาสรุปว่ายังไม่เข้า diacetyl_rest ทั้งที่ Pill เองถึงแล้ว)

6. cold_crash: ต้องผ่าน fg_stable (และปกติ diacetyl_rest) มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง) ลดลงเหลือ 0-4°C ค้างไว้ 1-3 วัน (ale ~1-2 วัน, lager ~2-3 วัน) — ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเช่นเดียวกับข้อ 5

หมายเหตุสำคัญ: ด้านล่างมี "ประวัติการปรับ target ด้วยมือ" ซึ่งผู้ควบคุมสั่งผ่านระบบพร้อมระบุเหตุผล (remark) เช่น "d rest" หรือ "cold crash" — ให้ใช้เป็นหลักฐานสนับสนุนสำคัญประกอบการตัดสินเฟส เพราะสะท้อนเจตนาจริงของผู้ควบคุม ไม่ใช่แค่ inference จากอุณหภูมิเพียงอย่างเดียว (เช่น ถ้าเพิ่งมีรายการปรับ target ขึ้นพร้อม remark "d rest" ให้ตีความว่ากำลังเข้าสู่ diacetyl_rest แม้ Pill จะยังไล่อุณหภูมิขึ้นไม่ถึง target ก็ตาม)

นอกจากตัดสินเฟสปัจจุบันแล้ว ให้ประมาณ "ไทม์ไลน์" ของเฟสที่ผ่านมาแล้วทั้งหมดจากกราฟทั้งเส้นด้วย (phase_timeline) — เอาแค่วันที่ (ไม่ต้องมีเวลา) เรียงจากเฟสแรกสุด (lag) ไล่ลงมาจนถึงเฟสปัจจุบัน แยก "high_krausen" (ช่วงพีคที่ SG ลดชันที่สุดของทั้งเส้น) ออกจาก "active_ferment" (ช่วงเริ่มลดก่อนถึงพีค) เป็นคนละรายการ แต่ละรายการมี summary สั้นๆ 1 บรรทัดบอกค่า SG/อุณหภูมิสำคัญของช่วงนั้น ไม่ต้องใส่เฟสที่ยังไม่เกิดขึ้นจริง (เฟสที่กำลังจะมาถึงให้ใส่แค่ใน next_phase/prep_actions ตามเดิม)

ข้อกำหนดเรื่องวันที่และความกระชับ: ทุกจุดที่ต้องระบุวันที่ (ทั้งใน phase_timeline และในข้อความ reasoning/prep_actions ถ้าต้องอ้างถึง) ให้ใช้รูปแบบ dd/mm/yyyy เท่านั้น (เช่น 17/08/2026) ห้ามใช้ชื่อเดือนภาษาอังกฤษ (Aug, Jan ฯลฯ) หรือรูปแบบ ISO (YYYY-MM-DD) เด็ดขาด และให้เขียนทุกข้อความสั้นกระชับที่สุดเท่าที่ยังสื่อความชัดเจน ไม่ใส่รายละเอียดที่ไม่จำเป็น

ข้อมูล batch "${batch.beer_name || '(ไม่ระบุชื่อ)'}":
- เริ่มหมักมาแล้ว: ${hoursSinceStart.toFixed(1)} ชั่วโมง (${(hoursSinceStart / 24).toFixed(1)} วัน)
- เฟสล่าสุดที่บันทึกไว้: ${batch.current_phase}
- อุณหภูมิ Pill (เบียร์จริง) ล่าสุด: ${latestPill && latestPill.temp != null ? latestPill.temp : 'ไม่มีข้อมูล'}°C ← ใช้ตัวนี้ตัดสิน diacetyl_rest/cold_crash เป็นหลัก
- อุณหภูมิหมักปกติของ batch นี้ (เฉลี่ย Pill ช่วง 72 ชม.แรก): ${fermentationBaselineTemp ?? 'ไม่มีข้อมูล'}°C ← baseline สำหรับเทียบว่ายกขึ้น +2 ถึง +4°C แล้วหรือยัง (diacetyl_rest)
- อุณหภูมิตู้ควบคุมล่าสุด: ${latestController && latestController.temp != null ? latestController.temp : 'ไม่มีข้อมูล'}°C (ข้อมูลเสริมเท่านั้น)
- target temperature ที่ตู้ควบคุมตั้งไว้ปัจจุบัน: ${latestController && latestController.target != null ? latestController.target : 'ไม่มีข้อมูล'}°C
- ส่วนต่างอุณหภูมิ Pill-ตู้ควบคุมช่วงที่นิ่งแล้ว (เฉลี่ยจากช่วงหลังปรับ target ล่าสุด, ${r.stable_gap_points ?? 0} จุด): ${r.stable_gap_c != null ? Number(r.stable_gap_c).toFixed(2) : 'ไม่มีข้อมูลพอ'}°C ← ใช้แปลง "อุณหภูมิ Pill ที่อยากได้" เป็น "target ที่ควรตั้งบนตู้ควบคุม" (target = pill เป้าหมาย - ส่วนต่างนี้)
${recipeContextText}

กราฟ gravity/อุณหภูมิ Pill ตามเวลา (${pillSeries.length} จุด, เรียงเก่า→ใหม่):
${pillSeriesText}

กราฟอุณหภูมิตู้ควบคุมตามเวลา (${controllerSeries.length} จุด, เรียงเก่า→ใหม่):
${controllerSeriesText}

ประวัติการปรับ target ด้วยมือ (${controlSeries.length} รายการ, เรียงเก่า→ใหม่):
${controlSeriesText}

ตอบกลับเป็น JSON เท่านั้น ห้ามมีข้อความอื่นปนก่อน/หลัง รูปแบบ:
{"phase": "<lag|active_ferment|slowing_ferment|fg_stable|diacetyl_rest|cold_crash>", "reasoning": ["<เหตุผลข้อที่ 1 สั้นๆ ภาษาไทย อ้างอิงข้อมูลที่ให้มาประกอบ>", "<เหตุผลข้อที่ 2>", "..."], "approaching_transition": <true|false>, "next_phase": <"lag"|"active_ferment"|"slowing_ferment"|"fg_stable"|"diacetyl_rest"|"cold_crash"|null>, "prep_actions": ["<ขั้นตอนเตรียมตัวข้อที่ 1>", "..."], "phase_timeline": [{"phase": "<lag|active_ferment|high_krausen|slowing_ferment|fg_stable|diacetyl_rest|cold_crash>", "from": "<DD/MM/YYYY>", "to": "<DD/MM/YYYY>", "summary": "<คำอธิบายสั้นๆ ไม่เกิน 1 บรรทัด>"}], "recommended_pill_temp_c": <number|null>}
reasoning และ prep_actions ต้องเป็น array ของ string สั้นๆ ไม่เกิน 4 ข้อ แต่ละข้อคือประเด็นเดียว ยาวไม่เกิน ~20 คำ ไม่ใช่ paragraph ยาวๆ phase_timeline ต้องเรียงจากเฟสแรกสุดไปเฟสปัจจุบัน ไม่ต้องใส่เฟสที่ยังไม่เกิดขึ้นจริง summary ของแต่ละช่วงยาวไม่เกิน ~12 คำ
recommended_pill_temp_c: ใส่เฉพาะตอน approaching_transition เป็น true และ next_phase เป็น diacetyl_rest หรือ cold_crash เท่านั้น (นอกนั้นใส่ null) คือ \"อุณหภูมิ Pill (เบียร์จริง) ที่อยากให้ไปถึง\" สำหรับเฟสถัดไป ไม่ใช่ target ของตู้ควบคุม — ถ้ามีแผนขั้นตอนจากสูตร Brewfather ด้านบนให้ใช้ค่า stepTemp ของ step ที่ตรงกับเฟสถัดไปเป็นหลัก ถ้าไม่มีแผนจากสูตรให้ประมาณเองตามเกณฑ์เดิม (baseline+2 ถึง +4°C สำหรับ diacetyl_rest, 0-4°C สำหรับ cold_crash)`;

  // ABV แบบสูตรง่าย (simple formula) ที่ homebrew calculator ทั่วไปใช้ default:
  // ABV% = (OG - FG) * 131.25 — จุดแรกของ pillSeries คือ OG (นับตั้งแต่ start_date),
  // จุดล่าสุดคือ FG ปัจจุบัน (ยังไม่ใช่ FG จริงจนกว่าจะถึง fg_stable แต่คำนวณ
  // ABV คร่าวๆ ไว้ดูความคืบหน้าได้ระหว่างทาง)
  const ogSg = pillSeries.length ? pillSeries[0].sg : null;
  const currentSg = latestPill ? latestPill.sg : null;
  const abvPercent = (ogSg != null && currentSg != null)
    ? Number(((ogSg - currentSg) * 131.25).toFixed(2))
    : null;

  results.push({
    json: {
      batch_id: batch.batch_id,
      beer_name: batch.beer_name,
      current_phase: batch.current_phase,
      prep_alerted_for_phase: batch.prep_alerted_for_phase,
      gravity_sg: latestPill ? latestPill.sg : null,
      temperature_c: latestPill ? latestPill.temp : null,
      gravity_velocity: loggedVelocity,
      controller_temp_c: latestController ? latestController.temp : null,
      target_temperature_c: latestController ? latestController.target : null,
      abv_percent: abvPercent,
      recipe_id: r.recipe_id ?? null,
      stable_gap_c: r.stable_gap_c ?? null,
      stable_gap_points: r.stable_gap_points ?? 0,
      prompt: promptText
    }
  });
});
return results;

// comma ในข้อความ reasoning/prep_actions ทำให้ Postgres queryReplacement
// (comma-separated string แบบเก่าที่ node นี้ใช้) เลื่อนตำแหน่ง parameter
// ผิด จนข้อความทั้งก้อนไปตกอยู่ใน parameter ตัวเลข แล้ว insert พัง
// แทนที่ comma ด้วยรูปเต็มความกว้าง (，) กันปัญหานี้แบบไม่กระทบการอ่าน
function sanitizeForQueryReplacement(text) {
  return typeof text === 'string' ? text.replace(/,/g, '，') : text;
}
// gravity ปัด 3 ตำแหน่ง, อุณหภูมิปัด 2 ตำแหน่ง — ตัดหางทศนิยมยาวๆ จาก sensor/DB
// (เช่น 17.3434753417969) ทั้งที่จะ insert ลง phase_log และตอนไปแสดงผลใน Discord
function round(v, n) {
  return v == null ? null : Number(Number(v).toFixed(n));
}

const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  const src = $('Build AI Prompt').itemMatching(idx).json;
  let phase = null, reasoning = null;
  let approachingTransition = false, nextPhase = null, prepActionsText = '', phaseTimelineText = '', recommendedPillTempC = null;
  try {
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    let text = textBlock ? textBlock.text : undefined;
    // Claude บางทีห่อ JSON ด้วย markdown code fence (```json ... ```) ทั้งที่ prompt
    // สั่งห้ามแล้ว ตัดออกก่อน parse กันพัง (เจอจริงตอน prompt ยาวขึ้นหลังส่ง series เต็ม)
    if (text) {
      text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
    }
    const parsed = JSON.parse(text);
    phase = parsed.phase;
    reasoning = sanitizeForQueryReplacement(Array.isArray(parsed.reasoning)
      ? parsed.reasoning.map(line => '• ' + line).join('\n')
      : String(parsed.reasoning));
    approachingTransition = parsed.approaching_transition === true;
    nextPhase = parsed.next_phase || null;
    const prepActionsArr = Array.isArray(parsed.prep_actions) ? parsed.prep_actions : [];
    prepActionsText = sanitizeForQueryReplacement(prepActionsArr.map(a => '• ' + a).join('\n'));
    const timelineArr = Array.isArray(parsed.phase_timeline) ? parsed.phase_timeline : [];
    phaseTimelineText = sanitizeForQueryReplacement(timelineArr.map(p => `• ${p.phase}: ${p.from} - ${p.to} | ${p.summary}`).join('\n'));
    recommendedPillTempC = typeof parsed.recommended_pill_temp_c === 'number' ? round(parsed.recommended_pill_temp_c, 2) : null;
  } catch (e) {
    // JSON เต็มพัง (เช่น Claude ลืม escape ตัวอักษรในข้อความ ทำให้ string ใน
    // JSON ปิดไม่ครบ) แต่บางทีค่า "phase" เองยังอ่านได้ด้วย regex ตรงๆ กู้เอาไว้
    // ดีกว่าทิ้งไปเลยทั้งที่ AI ตัดสินใจแล้วจริงๆ แค่ format ตอนท้ายพัง
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    const rawText = textBlock ? textBlock.text : '';
    const phaseMatch = rawText.match(/"phase"\s*:\s*"([a-z_]+)"/);
    if (phaseMatch) {
      phase = phaseMatch[1];
      reasoning = sanitizeForQueryReplacement('⚠️ กู้ phase จาก JSON ที่ไม่สมบูรณ์ (regex fallback, ' + String(e) + ')');
    } else {
      phase = src.current_phase; // กู้อะไรไม่ได้เลย -> คงเฟสเดิมไว้ก่อน ไม่เปลี่ยนมั่ว
      reasoning = sanitizeForQueryReplacement('AI response parse error: ' + String(e));
    }
    // approachingTransition/nextPhase/prepActionsText คงค่า default (false/null/'') ไว้ ไม่เดา
  }
  // ส่ง prep alert แค่ครั้งเดียวต่อ next_phase หนึ่งค่า กัน spam ทุก 30 นาที
  // จนกว่า AI จะเปลี่ยนใจ (next_phase อื่น) หรือเฟสเปลี่ยนจริง (reset ที่ Update Batch Phase)
  const shouldSendPrepAlert = approachingTransition
    && !!nextPhase
    && nextPhase !== src.prep_alerted_for_phase;

  // target ที่ควรตั้งบนตู้ควบคุมจริง = อุณหภูมิ Pill ที่ AI แนะนำ ลบด้วยส่วนต่าง Pill-ตู้ควบคุม
  // ช่วงนิ่ง (stable_gap_c) เพราะ Pill (เบียร์จริง) กับตู้ควบคุม (อากาศ) มักมีส่วนต่างค้างอยู่
  // เสมอแม้ตอนนิ่งแล้ว ถ้าไม่มีข้อมูลส่วนต่างพอ (ยังไม่นิ่ง/เพิ่งเริ่ม batch) จะไม่แนะนำปุ่มให้
  const recommendedControllerTargetC = (recommendedPillTempC != null && src.stable_gap_c != null)
    ? round(recommendedPillTempC - src.stable_gap_c, 2)
    : null;
  results.push({
    json: {
      batch_id: src.batch_id,
      beer_name: src.beer_name,
      previous_phase: src.current_phase,
      detected_phase: phase,
      reasoning,
      gravity_sg: round(src.gravity_sg, 3),
      temperature_c: round(src.temperature_c, 2),
      gravity_velocity: src.gravity_velocity,
      controller_temp_c: round(src.controller_temp_c, 2),
      target_temperature_c: round(src.target_temperature_c, 2),
      abv_percent: round(src.abv_percent, 2),
      next_phase: nextPhase,
      prep_actions_text: prepActionsText,
      phase_timeline_text: phaseTimelineText,
      should_send_prep_alert: shouldSendPrepAlert,
      recommended_pill_temp_c: recommendedPillTempC,
      recommended_controller_target_c: recommendedControllerTargetC
    }
  });
});
return results;

const items = $input.all();
const results = [];

// toFixed เพื่อให้เลขทศนิยมแสดงจำนวนหลักคงที่เสมอ (เช่น 20.00 ไม่ใช่ 20)
// ต่างจาก round() ใน Parse AI Response ที่ปัดค่าไว้ใช้ต่อ/insert DB เท่านั้น
function fmt(v, n) {
  return v == null ? '-' : Number(v).toFixed(n);
}

// loop ทุก item (1 item = 1 batch active) — เดิมใช้ $input.first() ตัวเดียว
// ทำให้ตอนมีมากกว่า 1 batch active พร้อมกัน ยิงข้อความให้แค่ batch แรกเท่านั้น
// batch อื่นหายไปเงียบๆ (เจอจริงตอนมี 2 batch active พร้อมกัน)
items.forEach((it) => {
  const d = it.json;
  const sections = [];

  const header = '📋 อัปเดตสถานะ: ' + d.beer_name
    + '\nเฟส: ' + d.detected_phase
    + (d.detected_phase !== d.previous_phase ? (' 🔔 (เปลี่ยนจาก ' + d.previous_phase + ')') : '')
    + (d.next_phase ? (' ใกล้ ' + d.next_phase) : '')
    + '\ngravity: ' + fmt(d.gravity_sg, 3) + ' SG, Pill: ' + fmt(d.temperature_c, 2) + '°C'
    + '\nตู้ควบคุม: ' + fmt(d.controller_temp_c, 2) + '°C (target ' + fmt(d.target_temperature_c, 2) + '°C)'
    + '\nABV: ~' + fmt(d.abv_percent, 2) + '%';
  sections.push(header);

  if (d.phase_timeline_text) {
    sections.push('⏱️ ไทม์ไลน์การหมัก:\n' + d.phase_timeline_text);
  }

  sections.push(d.reasoning);

  if (d.next_phase) {
    sections.push('🔜 ใกล้เข้าเฟส ' + d.next_phase + ':\n' + d.prep_actions_text);
  }

  if (d.recommended_controller_target_c != null) {
    sections.push('🌡️ แนะนำตั้ง target ใหม่ ' + fmt(d.recommended_controller_target_c, 2) + '°C (ให้ Pill ถึง ' + fmt(d.recommended_pill_temp_c, 2) + '°C ตามแผน)');
  }

  const LIMIT = 1900;
  const chunks = [];
  for (const section of sections) {
    if (section.length <= LIMIT) {
      chunks.push(section);
    } else {
      for (let i = 0; i < section.length; i += LIMIT) {
        chunks.push(section.slice(i, i + LIMIT));
      }
    }
  }

  chunks.forEach((content, i) => {
    results.push({
      json: {
        content,
        is_last: i === chunks.length - 1,
        batch_id: d.batch_id,
        recommended_controller_target_c: d.recommended_controller_target_c,
        recommended_pill_temp_c: d.recommended_pill_temp_c,
        next_phase: d.next_phase
      }
    });
  });
});

return results;
